mapper.select:
SELECT sif.id AS id, sif.item_id AS item_id, sif.type AS type, sf.object_name AS object_name, sf.storage AS storage, sf_t.object_name AS thumbnail_object_name, sf_t.storage AS thumbnail_storage, sif.description AS description, sif.width AS width, sif.height AS height, sif.scene_type AS scene_type, sif.haze_level AS haze_level FROM sys_item_file sif JOIN sys_file sf ON sif.file_id = sf.id LEFT JOIN sys_file sf_t ON sif.thumbnail_file_id = sf_t.id WHERE sif.item_id IN
#{itemId}
ORDER BY sif.item_id, sif.type
